package com.wesbos.homehq;

import android.app.*;
import android.app.job.*;
import android.content.*;
import android.content.pm.*;
import android.os.Build;
import android.os.SystemClock;
import org.json.*;
import java.io.*;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Fixed public release source; APK trust is anchored to our installed certificate. */
final class AppUpdates {
  private static AppUpdates instance;
  static synchronized AppUpdates get(Context c){if(instance==null)instance=new AppUpdates(c.getApplicationContext());return instance;}
  private final Context context;
  private final SharedPreferences prefs;
  private final ExecutorService worker=Executors.newSingleThreadExecutor();
  private final AtomicBoolean busy=new AtomicBoolean();
  private final File apk;
  private volatile String stage="idle",message="",release="",notes="",url="",hash="";
  private volatile long candidate;
  private volatile boolean eligible,restoring;
  private volatile long heartbeat,touch=SystemClock.elapsedRealtime();
  private AppUpdates(Context c){context=c;prefs=c.getSharedPreferences("skylit-updates",Context.MODE_PRIVATE);File dir=new File(c.getFilesDir(),"updates");dir.mkdirs();apk=new File(dir,"ready.apk");if(Build.VERSION.SDK_INT>=28){restoring=true;busy.set(true);stage="checking";worker.execute(()->{try{restore();schedule();}finally{restoring=false;busy.set(false);}});}else stage="unsupported";}
  private long installed(){try{return context.getPackageManager().getPackageInfo(context.getPackageName(),0).versionCode;}catch(Exception e){return 0;}}
  private String installedName(){try{return context.getPackageManager().getPackageInfo(context.getPackageName(),0).versionName;}catch(Exception e){return "";}}
  private void restore(){candidate=prefs.getLong("candidate",0);release=prefs.getString("release","");notes=prefs.getString("notes","");url=prefs.getString("url","");hash=prefs.getString("hash","");int session=prefs.getInt("session",-1);if(candidate<=installed()){clear();return;}if(session>=0&&context.getPackageManager().getPackageInstaller().getSessionInfo(session)!=null){stage="installing";return;}prefs.edit().remove("session").apply();if(apk.isFile()){try{verify(apk);stage="ready";}catch(Exception e){apk.delete();stage="available";}}else if(!url.isEmpty())stage="available";}
  private void clear(){apk.delete();new File(apk.getParentFile(),"download.part").delete();prefs.edit().remove("candidate").remove("release").remove("notes").remove("url").remove("hash").remove("session").remove("pendingIntent").remove("installError").apply();candidate=0;release=notes=url=hash="";stage="idle";}
  synchronized String status(){JSONObject j=new JSONObject();try{j.put("supported",Build.VERSION.SDK_INT>=28).put("installed",installedName()).put("installedCode",installed()).put("stage",restoring?"checking":prefs.contains("pendingIntent")?"confirm":stage).put("message",prefs.contains("installError")?"Android could not complete the update. Try again.":message).put("version",release).put("notes",notes).put("lastChecked",prefs.getLong("checked",0)).put("permission",(Build.VERSION.SDK_INT>=26&&context.getPackageManager().canRequestPackageInstalls())).put("settings",new JSONObject().put("check",prefs.getBoolean("check",true)).put("download",prefs.getBoolean("download",false)).put("install",prefs.getBoolean("install",false)).put("start",prefs.getInt("start",2)).put("end",prefs.getInt("end",4)).put("timezone",prefs.getString("timezone","UTC")));}catch(Exception ignored){}return j.toString();}
  boolean configure(String raw){try{JSONObject j=new JSONObject(raw);int start=j.getInt("start"),end=j.getInt("end");String tz=j.getString("timezone");if(start<0||start>23||end<0||end>23||start==end||!Arrays.asList(TimeZone.getAvailableIDs()).contains(tz))return false;boolean install=j.getBoolean("install"),download=j.getBoolean("download")||install,check=j.getBoolean("check")||download;if(!prefs.edit().putBoolean("check",check).putBoolean("download",download).putBoolean("install",install).putInt("start",start).putInt("end",end).putString("timezone",tz).commit())return false;schedule();return true;}catch(Exception e){return false;}}
  void schedule(){JobScheduler jobs=(JobScheduler)context.getSystemService(Context.JOB_SCHEDULER_SERVICE);if(jobs==null)return;if(!prefs.getBoolean("check",true)){jobs.cancel(2160);return;}jobs.schedule(new JobInfo.Builder(2160,new ComponentName(context,UpdateJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(12*60*60*1000L).setPersisted(true).build());}
  void check(boolean manual,Runnable done){if(Build.VERSION.SDK_INT<28){if(done!=null)done.run();return;}if(!busy.compareAndSet(false,true)){if(done!=null)done.run();return;}worker.execute(()->{try{if(!manual&&!prefs.getBoolean("check",true))return;if(context.getPackageManager().getPackageInstaller().getSessionInfo(prefs.getInt("session",-1))!=null)return;stage="checking";message="";JSONObject response=new JSONObject(new String(fetch("https://api.github.com/repos/sachasayan/skylit/releases/latest",1024*1024),java.nio.charset.StandardCharsets.UTF_8));if(response.optBoolean("draft")||response.optBoolean("prerelease"))throw new IOException();String tag=response.getString("tag_name");if(!tag.startsWith("v")||!UpdatePolicy.version(tag.substring(1)))throw new IOException();String version=tag.substring(1),metadata=asset(response,"update.json",version);prefs.edit().putLong("checked",System.currentTimeMillis()).apply();if(metadata==null){stage=apk.isFile()?"ready":candidate>installed()?"available":"current";message="No newer verified release is published.";return;}JSONObject data=new JSONObject(new String(fetch(metadata,32768),java.nio.charset.StandardCharsets.UTF_8));Object code=data.get("versionCode");if(!(code instanceof Integer||code instanceof Long)||!data.getString("versionName").equals(version)||!UpdatePolicy.hash(data.getString("sha256"))||!data.getString("package").equals(context.getPackageName())||data.getInt("minSdk")>Build.VERSION.SDK_INT)throw new IOException();long next=((Number)code).longValue();if(!UpdatePolicy.newer(installed(),next)){clear();stage="current";return;}String name="skylit-"+version+".apk",source=asset(response,name,version);if(source==null||!name.equals(data.getString("asset")))throw new IOException();if(candidate!=next||!hash.equals(data.getString("sha256"))){apk.delete();prefs.edit().remove("pendingIntent").remove("session").remove("installError").apply();}candidate=next;release=version;url=source;hash=data.getString("sha256");notes=response.optString("body","");if(notes.length()>6000)notes=notes.substring(0,6000);prefs.edit().putLong("candidate",candidate).putString("release",release).putString("url",url).putString("hash",hash).putString("notes",notes).commit();stage=apk.isFile()?"ready":"available";if(prefs.getBoolean("download",false)&&!apk.isFile())downloadNow();}catch(Exception e){stage=apk.isFile()?"ready":candidate>installed()?"available":"failed";message="Could not check updates. Check your connection and try again.";}finally{busy.set(false);if(done!=null)done.run();}});}
  private String asset(JSONObject response,String name,String version)throws Exception{JSONArray list=response.getJSONArray("assets");String found=null;for(int i=0;i<Math.min(list.length(),100);i++){JSONObject a=list.getJSONObject(i);if(name.equals(a.optString("name"))){String u=a.getString("browser_download_url");if(found!=null||!UpdatePolicy.asset(u,version,name))throw new IOException();found=u;}}return found;}
  void download(){if(Build.VERSION.SDK_INT<28)return;if(!busy.compareAndSet(false,true))return;worker.execute(()->{try{downloadNow();}catch(Exception e){stage=candidate>installed()?"available":"failed";message="Download could not be verified. Retry when connected.";}finally{busy.set(false);}});}
  private void downloadNow()throws Exception{if(!UpdatePolicy.newer(installed(),candidate)||!UpdatePolicy.asset(url,release,"skylit-"+release+".apk"))throw new IOException();stage="downloading";message="";File part=new File(apk.getParentFile(),"download.part");HttpURLConnection download=connection(url);try{try(InputStream in=download.getInputStream();OutputStream out=new FileOutputStream(part)){byte[] buffer=new byte[32768];long total=0,deadline=SystemClock.elapsedRealtime()+120000;int n;while((n=in.read(buffer))>=0){if(SystemClock.elapsedRealtime()>deadline)throw new IOException();total+=n;if(total>64L*1024*1024)throw new IOException();out.write(buffer,0,n);}}verify(part);if(!part.renameTo(apk))throw new IOException();prefs.edit().remove("installError").apply();stage="ready";}finally{download.disconnect();part.delete();}}
  private HttpURLConnection connection(String source)throws Exception{String current=source;for(int i=0;i<6;i++){if(!current.equals("https://api.github.com/repos/sachasayan/skylit/releases/latest")&&!UpdatePolicy.downloadHost(current))throw new IOException();HttpURLConnection c=(HttpURLConnection)new URL(current).openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Skylit-Updater");c.setRequestProperty("Accept",current.startsWith("https://api.github.com/")?"application/vnd.github+json":"application/octet-stream");int status=c.getResponseCode();if(status>=300&&status<=399){String location=c.getHeaderField("Location");c.disconnect();current=new URL(new URL(current),location).toString();continue;}if(status!=200){c.disconnect();throw new IOException();}return c;}throw new IOException();}
  private byte[] fetch(String source,int maximum)throws Exception{HttpURLConnection c=connection(source);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];long deadline=SystemClock.elapsedRealtime()+120000;int n;while((n=in.read(b))>=0){if(SystemClock.elapsedRealtime()>deadline||out.size()+n>maximum)throw new IOException();out.write(b,0,n);}return out.toByteArray();}finally{c.disconnect();}}
  private void verify(File file)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[32768];int n;while((n=in.read(b))>=0)digest.update(b,0,n);}StringBuilder result=new StringBuilder();for(byte b:digest.digest())result.append(String.format(Locale.ROOT,"%02x",b&255));if(!result.toString().equals(hash))throw new IOException();PackageManager pm=context.getPackageManager();PackageInfo next=pm.getPackageArchiveInfo(file.getPath(),PackageManager.GET_SIGNING_CERTIFICATES),own=pm.getPackageInfo(context.getPackageName(),PackageManager.GET_SIGNING_CERTIFICATES);if(next==null||!own.packageName.equals(next.packageName)||next.getLongVersionCode()!=candidate||!release.equals(next.versionName)||!UpdatePolicy.newer(own.getLongVersionCode(),candidate)||next.signingInfo==null||own.signingInfo==null||next.signingInfo.hasMultipleSigners()||own.signingInfo.hasMultipleSigners())throw new IOException();Signature[] ours=own.signingInfo.getApkContentsSigners(),theirs=next.signingInfo.getApkContentsSigners();if(ours.length!=1||theirs.length!=1||!ours[0].equals(theirs[0]))throw new IOException();}
  void permission(Activity activity){try{activity.startActivity(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,android.net.Uri.parse("package:"+context.getPackageName())));}catch(Exception unavailable){message="Android installation settings are unavailable. Open Android Settings manually.";}}
  private boolean automaticAllowed(){Calendar clock=Calendar.getInstance(TimeZone.getTimeZone(prefs.getString("timezone","UTC")));return prefs.getBoolean("install",false)&&!prefs.contains("installError")&&UpdatePolicy.idle(SystemClock.elapsedRealtime(),touch,heartbeat,eligible)&&UpdatePolicy.window(clock.get(Calendar.HOUR_OF_DAY),prefs.getInt("start",2),prefs.getInt("end",4));}
  void install(Activity activity,boolean automatic){
    if(Build.VERSION.SDK_INT<28||busy.get()||automatic&&!automaticAllowed())return;
    if(!context.getPackageManager().canRequestPackageInstalls()){if(!automatic)permission(activity);return;}
    if(prefs.contains("pendingIntent")){if(!automatic)try{activity.startActivity(Intent.parseUri(prefs.getString("pendingIntent",""),Intent.URI_INTENT_SCHEME));}catch(Exception e){prefs.edit().remove("pendingIntent").apply();stage="ready";}return;}
    if(!"ready".equals(stage)||!busy.compareAndSet(false,true))return;
    worker.execute(()->{int id=-1;try{
      try{verify(apk);}catch(Exception invalid){apk.delete();prefs.edit().remove("installError").apply();stage="available";message="The cached update could not be verified. Download it again.";return;}PackageInstaller installer=context.getPackageManager().getPackageInstaller();
      PackageInstaller.SessionParams params=new PackageInstaller.SessionParams(PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(context.getPackageName());params.setSize(apk.length());
      if(Build.VERSION.SDK_INT>=31)params.setRequireUserAction(automatic?PackageInstaller.SessionParams.USER_ACTION_NOT_REQUIRED:PackageInstaller.SessionParams.USER_ACTION_REQUIRED);
      id=installer.createSession(params);
      if(!prefs.edit().putInt("session",id).remove("installError").commit())throw new IOException();
      try(PackageInstaller.Session session=installer.openSession(id)){
        try(InputStream in=new FileInputStream(apk);OutputStream out=session.openWrite("base.apk",0,apk.length())){byte[] buffer=new byte[32768];int n;while((n=in.read(buffer))>=0)out.write(buffer,0,n);session.fsync(out);}
        // The stream must be closed before commit; also recheck any idle/opt-in change.
        if(automatic&&!automaticAllowed())throw new IOException();
        Intent callback=new Intent(context,UpdateReceiver.class).setAction("com.wesbos.homehq.UPDATE_RESULT").putExtra("expectedSession",id);
        PendingIntent pending=PendingIntent.getBroadcast(context,id,callback,PendingIntent.FLAG_UPDATE_CURRENT|(Build.VERSION.SDK_INT>=31?PendingIntent.FLAG_MUTABLE:0));
        stage="installing";session.commit(pending.getIntentSender());
      }
    }catch(Exception e){if(id>=0)try{context.getPackageManager().getPackageInstaller().abandonSession(id);}catch(Exception ignored){}prefs.edit().remove("session").apply();if(automatic&&automaticAllowed())prefs.edit().putBoolean("installError",true).apply();stage="ready";message=automatic?"Update is ready; automatic installation is deferred.":"Could not start installation. Try again.";}finally{busy.set(false);}});
  }
  void activity(boolean ready){heartbeat=SystemClock.elapsedRealtime();eligible=ready;}
  void touched(){touch=SystemClock.elapsedRealtime();eligible=false;}
  void result(Intent intent){worker.execute(()->receiveResult(intent));}
  private void receiveResult(Intent intent){int expected=prefs.getInt("session",-1);if(expected<0||intent.getIntExtra("expectedSession",-2)!=expected||intent.getIntExtra(PackageInstaller.EXTRA_SESSION_ID,-2)!=expected)return;int status=intent.getIntExtra(PackageInstaller.EXTRA_STATUS,PackageInstaller.STATUS_FAILURE);if(status==PackageInstaller.STATUS_PENDING_USER_ACTION){Intent confirmation=intent.getParcelableExtra(Intent.EXTRA_INTENT);if(confirmation!=null)prefs.edit().putString("pendingIntent",confirmation.toUri(Intent.URI_INTENT_SCHEME)).apply();}else if(status==PackageInstaller.STATUS_SUCCESS){clear();stage="current";}else{prefs.edit().remove("pendingIntent").remove("session").putBoolean("installError",true).apply();stage="ready";}}
}
